// App.js
import React, { useMemo, useState, useEffect } from "react";
import LoginForm from "./LoginForm";
import SignupForm from "./SignupForm";
import ProfileSetup from "./ProfileSetup";
import BudgetPreference from "./BudgetPreference";
import LocationPreference from "./LocationPreference";
import SleepSchedule from "./SleepSchedule";

const STEPS = {
  LOGIN: "login",
  SIGNUP: "signup",
  PROFILE: "profile",
  BUDGET: "budget",
  LOCATION: "location",
  SLEEP: "sleep",
  DONE: "done",
};

export default function App() {
  // where the user ends up after signup
  const [step, setStep] = useState(STEPS.LOGIN);

  // minimal “auth” placeholder for demo purposes
  const [user, setUser] = useState(null); // { id, email, ... }

  // collect everything you want to show at the end
  const [profile, setProfile] = useState(null);     // from ProfileSetup
  const [budget, setBudget] = useState(null);       // from BudgetPreference
  const [location, setLocation] = useState(null);   // from LocationPreference
  const [sleep, setSleep] = useState(null);         // from SleepSchedule
  const [loginMessage, setLoginMessage] = useState("");

  // Optional: restore progress if you want
  useEffect(() => {
    const saved = localStorage.getItem("reelty-signup-flow");
    if (!saved) return;
    try {
      const parsed = JSON.parse(saved);
      if (parsed.user) setUser(parsed.user);
      if (parsed.profile) setProfile(parsed.profile);
      if (parsed.budget) setBudget(parsed.budget);
      if (parsed.location) setLocation(parsed.location);
      if (parsed.sleep) setSleep(parsed.sleep);
      if (parsed.step) setStep(parsed.step);
    } catch (_) {}
  }, []);

  // Persist progress so refresh doesn’t lose state (optional)
  useEffect(() => {
    const toSave = { user, profile, budget, location, sleep, step };
    localStorage.setItem("reelty-signup-flow", JSON.stringify(toSave));
  }, [user, profile, budget, location, sleep, step]);

  const finalPayload = useMemo(
    () => ({
      user,
      profile,
      budget,
      location,
      sleep,
      createdAt: new Date().toISOString(),
    }),
    [user, profile, budget, location, sleep]
  );

  // ===== Handlers for each step =====

  // LoginForm should call onSuccess(userObj) if credentials are valid,
  // or onNoAccount() if the user clicks “No account? Sign up”
  const handleLoginSuccess = (existingUser) => {
    setUser(existingUser);
    setLoginMessage("Login successful ✅");
    // For your requirement: stop here after a successful login.
    setStep(STEPS.DONE);
  };
  const handleNoAccount = () => setStep(STEPS.SIGNUP);

  // SignupForm should call onComplete(newUserObj)
  const handleSignupComplete = (newUserObj) => {
    setUser(newUserObj);
    setStep(STEPS.PROFILE);
  };

  // ProfileSetup should call onNext(profileData)
  const handleProfileNext = (data) => {
    setProfile(data);
    setStep(STEPS.BUDGET);
  };

  // BudgetPreference should call onNext(budgetData)
  const handleBudgetNext = (data) => {
    setBudget(data);
    setStep(STEPS.LOCATION);
  };

  // LocationPreference should call onNext(locationData)
  const handleLocationNext = (data) => {
    setLocation(data);
    setStep(STEPS.SLEEP);
  };

  // SleepSchedule should call onNext(sleepData)
  const handleSleepNext = (data) => {
    setSleep(data);
    setStep(STEPS.DONE);
  };

  // ===== Render by step =====
  switch (step) {
    case STEPS.LOGIN:
      return (
        <LoginForm
          onSuccess={handleLoginSuccess}
          onNoAccount={handleNoAccount}
        />
      );

    case STEPS.SIGNUP:
      return <SignupForm onComplete={handleSignupComplete} />;

    case STEPS.PROFILE:
      return (
        <ProfileSetup
          initialData={profile || {}}
          onNext={handleProfileNext}
        />
      );

    case STEPS.BUDGET:
      return (
        <BudgetPreference
          initialData={budget || {}}
          onNext={handleBudgetNext}
        />
      );

    case STEPS.LOCATION:
      return (
        <LocationPreference
          initialData={location || {}}
          onNext={handleLocationNext}
        />
      );

    case STEPS.SLEEP:
      return (
        <SleepSchedule
          initialData={sleep || {}}
          onNext={handleSleepNext}
        />
      );

    case STEPS.DONE:
    default: {
      // If user came from login: show just “login successful”
      if (user && loginMessage && !profile && !budget && !location && !sleep) {
        return (
          <div style={{ padding: 24, maxWidth: 720, margin: "0 auto" }}>
            <h2>{loginMessage}</h2>
            <p>Welcome back{user?.email ? `, ${user.email}` : ""}.</p>
          </div>
        );
      }

      // If user completed the signup wizard: show final JSON/message
      return (
        <div style={{ padding: 24, maxWidth: 720, margin: "0 auto" }}>
          <h2>Account created 🎉</h2>
          <p>Here’s what we saved from your setup:</p>
          <pre
            style={{
              background: "#111",
              color: "#eee",
              padding: 16,
              borderRadius: 8,
              overflowX: "auto",
              lineHeight: 1.4,
            }}
          >
            {JSON.stringify(finalPayload, null, 2)}
          </pre>
        </div>
      );
    }
  }
}
